import os
import boto3

def extract_key_values(payload, config=None):
    config = config or {}
    region = config.get('region', 'us-east-1')
    client = boto3.client(
        'textract',
        region_name=region
    )
    response = client.analyze_document(
        Document={'Bytes': payload},
        FeatureTypes=['FORMS']
    )
    blocks = response['Blocks']
    blocks_map = {block['Id']: block for block in blocks}
    def get_text(block_id, blocks_map):
        block = blocks_map[block_id]
        text = block.get('Text', '')
        if 'Relationships' in block:
            for relationship in block['Relationships']:
                if relationship['Type'] == 'CHILD':
                    for child_id in relationship['Ids']:
                        text += ' ' + get_text(child_id, blocks_map)
        return text.strip()
    key_values = {}
    for block in blocks:
        if block['BlockType'] == 'KEY_VALUE_SET':
            for relationship in block['Relationships']:
                if relationship['Type'] == 'VALUE':
                    key_id = block['Id']
                    val_id = relationship['Ids'][0]
                    key_text = get_text(key_id, blocks_map)
                    val_text = get_text(val_id, blocks_map)
                    key_values[key_text] = val_text
                    break
    result = key_values
    return result
